CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text UNIQUE NOT NULL, password text NOT NULL, role text NOT NULL CHECK(role IN ('CUSTOMER','ADMIN')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE societies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,location text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE society_memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,society_id uuid NOT NULL REFERENCES societies,flat text NOT NULL,status text NOT NULL CHECK(status IN ('PENDING','APPROVED','REJECTED')),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(user_id,society_id));
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL);
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category_id uuid REFERENCES categories,name text NOT NULL,brand text NOT NULL,pack_size text NOT NULL,image text NOT NULL DEFAULT '🌾',active boolean NOT NULL DEFAULT true,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE supplier_products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),supplier_id uuid NOT NULL REFERENCES suppliers,product_id uuid NOT NULL REFERENCES products,cost_paise bigint NOT NULL CHECK(cost_paise>=0),UNIQUE(supplier_id,product_id));
CREATE TABLE buying_cycles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),society_id uuid NOT NULL REFERENCES societies,name text NOT NULL,starts_at timestamptz NOT NULL,cutoff_at timestamptz NOT NULL,minimum_paise bigint NOT NULL CHECK(minimum_paise>=0),status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','SUCCESS','FAILED')),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),CHECK(cutoff_at>starts_at));
CREATE TABLE cycle_product_prices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cycle_id uuid NOT NULL REFERENCES buying_cycles,product_id uuid NOT NULL REFERENCES products,supplier_id uuid NOT NULL REFERENCES suppliers,price_paise bigint NOT NULL CHECK(price_paise>0),reference_paise bigint NOT NULL CHECK(reference_paise>=price_paise),cost_paise bigint NOT NULL CHECK(cost_paise>=0),reference_source text NOT NULL,stock integer NOT NULL CHECK(stock>=0),UNIQUE(cycle_id,product_id));
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,cycle_id uuid NOT NULL REFERENCES buying_cycles,idempotency_key text NOT NULL,total_paise bigint NOT NULL,savings_paise bigint NOT NULL,fee_paise bigint NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'PAYMENT_PENDING',method text NOT NULL,flat text NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(user_id,idempotency_key));
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders,product_id uuid NOT NULL REFERENCES products,supplier_id uuid NOT NULL REFERENCES suppliers,quantity integer NOT NULL CHECK(quantity>0),price_paise bigint NOT NULL,reference_paise bigint NOT NULL,cost_paise bigint NOT NULL,UNIQUE(order_id,product_id));
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid UNIQUE NOT NULL REFERENCES orders,provider text NOT NULL,status text NOT NULL DEFAULT 'PENDING',gateway_id text UNIQUE,created_at timestamptz DEFAULT now());
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payment_id uuid UNIQUE NOT NULL REFERENCES payments,amount_paise bigint NOT NULL,status text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE supplier_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cycle_id uuid NOT NULL REFERENCES buying_cycles,supplier_id uuid NOT NULL REFERENCES suppliers,status text NOT NULL DEFAULT 'CREATED',UNIQUE(cycle_id,supplier_id));
CREATE TABLE supplier_order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),supplier_order_id uuid NOT NULL REFERENCES supplier_orders,product_id uuid NOT NULL REFERENCES products,quantity bigint NOT NULL,cost_paise bigint NOT NULL,UNIQUE(supplier_order_id,product_id));
CREATE TABLE fulfillments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid UNIQUE NOT NULL REFERENCES orders,status text NOT NULL DEFAULT 'PROCESSING',updated_at timestamptz DEFAULT now());
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES users,action text NOT NULL,target_id uuid,created_at timestamptz DEFAULT now());
CREATE INDEX membership_lookup ON society_memberships(user_id,status);
CREATE INDEX orders_cycle ON orders(cycle_id,status);
CREATE INDEX orders_user ON orders(user_id,created_at);
CREATE INDEX cycle_society ON buying_cycles(society_id,cutoff_at);
CREATE INDEX order_items_order ON order_items(order_id);
